#!/bin/bash
set -e

echo "=================================================="
echo " Deploy: Spectacle Prescription redesign (Prism +"
echo " Type of Glass + Remarks, matching reference format)"
echo "=================================================="
echo ""
echo "1) Optometry workspace, Final Rx tab only:"
echo "   - New PRISM column (free-text, e.g. \"2^BI\") next to"
echo "     SPH/CYL/AXIS for both Dist and Near rows"
echo "   - New \"Type of Glass\" dropdown (Distance / Near /"
echo "     Bifocal / Progressive / Photochromatic / Contact"
echo "     Lens)"
echo "   - New \"Remarks\" free-text field"
echo "   Scoped to Final Rx only, since that is the tab that"
echo "   gets prescribed and printed -- Objective/Subjective"
echo "   stay measurement-only tabs, unchanged."
echo ""
echo "2) Print Prescription printout redesigned to match the"
echo "   reference slip: one compact table with RIGHT EYE /"
echo "   LEFT EYE as column groups (SPH, CYL, AXIS, PRISM,"
echo "   VISION), DISTANCE and ADD as rows, plus TYPE OF"
echo "   GLASS / USES / REMARKS / IPD below it."
echo ""
echo "DATABASE: already applied directly to both Supabase"
echo "projects -- added these columns to optometry_assessments:"
echo "  ref_final_re_dist_prism, ref_final_le_dist_prism,"
echo "  ref_final_re_near_prism, ref_final_le_near_prism,"
echo "  glasses_type, glasses_remarks"
echo "No action needed from you on the DB side."
echo ""

TARGET="app/(main)/optometry/[id]/optometry-workspace.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/(main)/optometry/actions.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/print-templates/actions.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

echo ""
echo "Done. Review the diff with:"
echo '  git diff "app/(main)/optometry/[id]/optometry-workspace.js" "app/(main)/optometry/actions.js" app/print-templates/actions.js'
echo ""
echo "NOTE: if the OPD Case Sheet or Glasses Prescription"
echo "templates have ever been customized via the in-app Print"
echo "Templates editor, the saved DB row overrides this code"
echo "default. To pick up the redesign, reset \"Spectacle"
echo "Prescription\" from that admin page (or delete the"
echo "print_templates row for template_key = 'glasses_prescription'"
echo "on both projects)."
